# LP-FT in plain PyTorch (model.head is the new linear layer)
for p in model.parameters():
    p.requires_grad = False
for p in model.head.parameters():
    p.requires_grad = True
train(model, lr=1e-2, epochs=E // 2)    # stage 1: linear probe

